package app

import gfx "../gfx"
import platform "../platform"
import "base:runtime"
import "core:fmt"
import sdl "vendor:sdl3"
import "vendor:sdl3/ttf"

WINDOW_TITLE :: "Plastella"
WINDOW_WIDTH :: 960
WINDOW_HEIGHT :: 540

// Define unused var to access runtime, it will only be loaded in ODIN_DEBUG mode
@(private)
_ :: runtime.Type_Info

App_Memory :: struct {
	should_shutdown: bool,
	force_reload:    bool,
	force_restart:   bool,
	time_prev_ns:    u64,
	dt:              f32,
	input:           platform.Input,
	renderer:        ^sdl.Renderer,
	gfx_mem:         ^gfx.Gfx_Memory,
}
mem: ^App_Memory

when ODIN_DEBUG {
	@(export)
	app_memory_layout_hash :: proc() -> u64 {
		FNV_OFFSET :: u64(1469598103934665603)
		seen := make(map[typeid]bool, 64, context.temp_allocator) // host will free each loop
		return layout_hash(type_info_of(App_Memory), FNV_OFFSET, &seen)
	}

	layout_hash :: proc(ti: ^runtime.Type_Info, seed: u64, seen: ^map[typeid]bool) -> u64 {
		PRIME :: u64(1099511628211)
		if ti == nil do return seed // rawptr elem, empty proc results, etc.
		h := (seed ~ u64(ti.size)) * PRIME
		if seen[ti.id] do return h // already walked this type
		seen[ti.id] = true

		#partial switch v in ti.variant {
		case runtime.Type_Info_Named:
			h = layout_hash(v.base, h, seen)
		case runtime.Type_Info_Struct:
			for i in 0 ..< int(v.field_count) {
				h = (h ~ u64(v.offsets[i])) * PRIME
				h = layout_hash(v.types[i], h, seen)
			}
		case runtime.Type_Info_Union:
			for variant in v.variants do h = layout_hash(variant, h, seen)
		case runtime.Type_Info_Array:
			h = layout_hash(v.elem, h, seen)
		case runtime.Type_Info_Enumerated_Array:
			h = layout_hash(v.elem, h, seen)
		case runtime.Type_Info_Slice:
			h = layout_hash(v.elem, h, seen)
		case runtime.Type_Info_Dynamic_Array:
			h = layout_hash(v.elem, h, seen)
		case runtime.Type_Info_Map:
			h = layout_hash(v.key, h, seen)
			h = layout_hash(v.value, h, seen)
		case runtime.Type_Info_Pointer:
			h = layout_hash(v.elem, h, seen) // nil for rawptr -> stops
		case runtime.Type_Info_Multi_Pointer:
			h = layout_hash(v.elem, h, seen)
		}
		return h
	}
}

@(export)
app_init :: proc(window: ^sdl.Window) {
	assert(window != nil, "app_init: window is nil")
	mem = new(App_Memory, context.allocator)

	// SDL Renderer memory
	mem.renderer = sdl.GetRenderer(window)
	assert(mem.renderer != nil, "cannot get renderer from window")

	// Gfx_Memory (and clay memory)
	w, h: i32
	size_ok := sdl.GetRenderOutputSize(mem.renderer, &w, &h)
	assert(size_ok, cast(string)sdl.GetError())
	mem.gfx_mem = gfx.gfx_init({w, h}, mem.renderer)

	mem.time_prev_ns = sdl.GetTicksNS()
}

@(export)
app_update :: proc() {
	when ODIN_DEBUG {
		mem.force_reload = false
		mem.force_restart = false
	}

	// Delta time computation
	now_ns := sdl.GetTicksNS()
	mem.dt = f32(now_ns - mem.time_prev_ns) / 1_000_000_000.0 // ns -> secs
	mem.time_prev_ns = now_ns

	// Process inputs
	platform.input_frame_begin(&mem.input)
	event: sdl.Event
	poll: for sdl.PollEvent(&event) {
		platform.input_event_process(&mem.input, &event)
	}
	if mem.input.quit do mem.should_shutdown = true
	when ODIN_DEBUG {
		if platform.key_pressed(&mem.input, .F5) do mem.force_reload = true
		if platform.key_pressed(&mem.input, .F6) do mem.force_restart = true
	}

	// Process graphics frame
	gfx.gfx_frame_begin(
		mem.gfx_mem,
		mem.renderer,
		mem.input.mouse.pos,
		platform.mouse_down(&mem.input, .Left),
		platform.mouse_scroll(&mem.input),
		mem.dt,
	)

	gfx.gfx_frame_end(mem.gfx_mem, mem.dt)
}

@(export)
app_shutdown :: proc() {
	if mem == nil do return

	// Gfx_Memory
	gfx.gfx_shutdown(mem.gfx_mem)
	mem.gfx_mem = nil

	// App_Memory
	free(mem)
	mem = nil
}

@(export)
app_memory :: proc() -> rawptr {
	return mem
}

@(export)
app_hot_reloaded :: proc(m: rawptr) {
	new_mem := (^App_Memory)(m)
	mem.renderer = new_mem.renderer
	mem.gfx_mem = new_mem.gfx_mem
}

@(export)
app_should_run :: proc() -> bool {
	return !mem.should_shutdown
}

@(export)
app_force_reload :: proc() -> bool {
	return mem.force_reload
}

@(export)
app_force_restart :: proc() -> bool {
	return mem.force_restart
}

@(export)
app_memory_size :: proc() -> int {
	return size_of(App_Memory)
}

/*
	Calls sdl.Init() then returns a newly created Plastella window

	Returns:
	- The sdl window pointer
*/
@(export)
app_window_create :: proc() -> ^sdl.Window {
	if !ttf.Init() {
		fmt.eprint("Failed to initialize TTF")
	}

	if !sdl.Init({.VIDEO}) {
		fmt.eprintf("SDL Error: %s\n", sdl.GetError())
		return nil
	}

	window := sdl.CreateWindow(
	WINDOW_TITLE,
	WINDOW_WIDTH,
	WINDOW_HEIGHT,
	{
		.RESIZABLE,
		.HIGH_PIXEL_DENSITY,
		// Hide window and show it after it's been configured to avoid white flash
		.HIDDEN,
	},
	)

	assert(window != nil, "failed to create window")

	// The renderer lives with the window (not app_init) so it survives hard
	// restarts; app_init re-fetches it with sdl.GetRenderer(window).
	renderer := sdl.CreateRenderer(window, nil)
	assert(renderer != nil, cast(string)sdl.GetError())

	if window != nil {
		// Will "jump" to center, but hidden will fix that
		sdl.SetWindowPosition(window, sdl.WINDOWPOS_CENTERED, sdl.WINDOWPOS_CENTERED)
		platform.setup_window(window)
		sdl.ShowWindow(window)
	}

	return window
}

/*
	Destroys the provided window if it exists, and then quits SDL

	Inputs:
	- window: pointer to sdl window to destroy
*/
@(export)
app_window_destroy :: proc(window: ^sdl.Window) {
	if window != nil {
		sdl.DestroyRenderer(sdl.GetRenderer(window))
		sdl.DestroyWindow(window)
		sdl.Quit()
		ttf.Quit()
	}
}

package gfx

import clay "../../vendor/clay"
import "core:c"
import "core:fmt"
import sdl "vendor:sdl3"
import "vendor:sdl3/ttf"

Gfx_Memory :: struct {
	clay_trace:      ^Clay_Trace,
	clay_ctx:        ^clay.Context,
	clay_mem:        [^]u8,
	clay_render_mem: ^Clay_Render_Memory,
}

gfx_init :: proc(
	size: [2]i32,
	renderer: ^sdl.Renderer,
	text_engine: ^ttf.TextEngine,
	fonts: []^ttf.Font,
) -> ^Gfx_Memory {
	mem := new(Gfx_Memory)

	// Clay Memory
	mem.clay_trace = new(Clay_Trace)
	ctx, clay_mem, render_mem := clay_init(size, mem.clay_trace, renderer, text_engine, fonts)
	mem.clay_ctx = ctx
	mem.clay_mem = clay_mem
	mem.clay_render_mem = render_mem

	return mem
}

gfx_shutdown :: proc(mem: ^Gfx_Memory) {
	if mem == nil do return

	// Clay Memory
	if mem.clay_render_mem != nil do free(mem.clay_render_mem)
	if mem.clay_mem != nil do free(mem.clay_mem)
	if mem.clay_ctx != nil do free(mem.clay_ctx)
	if mem.clay_trace != nil do free(mem.clay_trace)

	free(mem)
}

gfx_reload :: proc(mem: ^Gfx_Memory) {
	assert(mem != nil, "Cannot reload GFX; memory is nil")
	clay_reload(mem.clay_ctx, mem.clay_render_mem)
	// reload textures and fonts
}

gfx_frame_begin :: proc(
	mem: ^Gfx_Memory,
	renderer: ^sdl.Renderer,
	mouse_pos: [2]f32,
	mouse_left: bool,
	mouse_scroll: [2]f32,
	dt: f32,
) {
	// reset cursor
	w, h: c.int
	dimensions_ok := sdl.GetRenderOutputSize(renderer, &w, &h)
	if !dimensions_ok {
		fmt.eprint("failed to get screen dimensions for gfx_frame_begin")
		return
	}
	dimensions := clay.Dimensions{cast(f32)w, cast(f32)h}

	clay_layout_begin(
		mem.clay_render_mem,
		mem.clay_trace,
		dimensions,
		mouse_pos,
		mouse_left,
		mouse_scroll,
		dt,
	)
}

gfx_frame_end :: proc(mem: ^Gfx_Memory, dt: f32) {
	commands := clay.EndLayout(dt)
	clay_render_commands(mem.clay_render_mem, &commands)
}

package gfx

import "../../vendor/clay"
import "base:runtime"
import "core:c"
import "core:fmt"
import "core:math"
import sdl "vendor:sdl3"
import img "vendor:sdl3/image"
import "vendor:sdl3/ttf"

SEGMENTS_BASE :: 16
SEGMENTS_MAX :: 32
ARC_SEGMENTS_MAX :: 32
VERTS_MAX :: 12 + 8 * SEGMENTS_MAX
INDICES_MAX :: 30 + 12 * SEGMENTS_MAX

Clay_Render_Memory :: struct {
	renderer:    ^sdl.Renderer,
	text_engine: ^ttf.TextEngine,
	fonts:       []^ttf.Font,
}

Clay_Trace :: struct {
	phase:     string,
	file:      string,
	line:      int,
	had_error: bool,
}

@(require_results)
clay_init :: proc(
	size: [2]i32,
	clay_trace: ^Clay_Trace,
	renderer: ^sdl.Renderer,
	text_engine: ^ttf.TextEngine,
	fonts: []^ttf.Font,
) -> (
	^clay.Context,
	[^]u8,
	^Clay_Render_Memory,
) {
	min_size := clay.MinMemorySize()
	clay_mem := make([^]u8, min_size)

	arena := clay.CreateArenaWithCapacityAndMemory(cast(c.size_t)min_size, clay_mem)
	ctx := clay.Initialize(
		arena,
		{f32(size.x), f32(size.y)},
		{handler = err_handler, userData = clay_trace},
	)

	if ctx == nil || clay_trace.had_error {
		fmt.eprint("[clay] initalization failed\n")
		if clay_mem != nil {
			free(clay_mem)
		}
		return nil, nil, nil
	}

	mem := new(Clay_Render_Memory)

	mem.renderer = renderer
	mem.text_engine = text_engine
	mem.fonts = fonts

	clay.SetMeasureTextFunction(measure_text, mem)

	return ctx, clay_mem, mem
}

clay_reload :: proc(ctx: ^clay.Context, data: ^Clay_Render_Memory) {
	clay.SetCurrentContext(ctx)
	clay.SetMeasureTextFunction(measure_text, data)
}

clay_layout_begin :: proc(
	render_mem: ^Clay_Render_Memory,
	clay_trace: ^Clay_Trace,
	screen_dimensions: clay.Dimensions,
	mouse_pos: [2]f32,
	mouse_down: bool,
	scroll: [2]f32,
	dt: f32,
) {
	clay_error_reset(clay_trace)
	clay.SetLayoutDimensions(screen_dimensions)
	clay.SetPointerState(mouse_pos, mouse_down)
	clay.UpdateScrollContainers(true, scroll, dt)
	clay.BeginLayout()
}

// Call at the beginning of a frame
clay_error_reset :: proc(clay_trace: ^Clay_Trace) {
	clay_trace.had_error = false
}

clay_render_commands :: proc(
	data: ^Clay_Render_Memory,
	commands: ^clay.ClayArray(clay.RenderCommand),
) {
	assert(data != nil)
	assert(data.renderer != nil)

	sdl.SetRenderDrawBlendMode(data.renderer, sdl.BLENDMODE_BLEND)

	for i in 0 ..< commands.length {
		cmd := clay.RenderCommandArray_Get(commands, i)
		b := cmd.boundingBox
		rect := sdl.FRect{f32(i32(b.x)), f32(i32(b.y)), f32(i32(b.width)), f32(i32(b.height))}

		#partial switch cmd.commandType {
		case .Rectangle:
			render_rectangle(data, rect, cmd.renderData.rectangle)
		case .Text:
			render_text(data, rect, cmd.renderData.text)
		case .Image:
			tex := (^sdl.Texture)(cmd.renderData.image.imageData)
			dst := rect
			sdl.RenderTexture(data.renderer, tex, nil, &dst)
		case .Border:
			render_border(data, rect, cmd.renderData.border)
		case .ScissorStart:
			clip := sdl.Rect{i32(b.x), i32(b.y), i32(b.width), i32(b.height)}
			sdl.SetRenderClipRect(data.renderer, &clip)
		case .ScissorEnd:
			sdl.SetRenderClipRect(data.renderer, nil)
		case .None, .Custom, .OverlayColorStart, .OverlayColorEnd:
		// Not implemented
		}
	}
}

@(private = "file")
render_rectangle :: proc(
	data: ^Clay_Render_Memory,
	rect: sdl.FRect,
	cfg: clay.RectangleRenderData,
) {
	if cfg.cornerRadius.topLeft > 0 {
		fill_rounded_rect(data, rect, cfg.cornerRadius.topLeft, cfg.backgroundColor)
		return
	}
	col := color_u8(cfg.backgroundColor)
	sdl.SetRenderDrawColor(data.renderer, col.r, col.g, col.b, col.a)
	r := rect
	sdl.RenderFillRect(data.renderer, &r)
}

@(private = "file")
fill_rounded_rect :: proc(
	data: ^Clay_Render_Memory,
	rect: sdl.FRect,
	radius: f32,
	color: clay.Color,
) {
	fc := color_float(color)
	rr := min(radius, min(rect.w, rect.h) / 2)
	segments := clamp(int(rr * 0.5), SEGMENTS_BASE, SEGMENTS_MAX)

	verts: [VERTS_MAX]sdl.Vertex = ---
	indices: [INDICES_MAX]c.int = ---

	verts[0] = {{rect.x + rr, rect.y + rr}, fc, {0, 0}}
	verts[1] = {{rect.x + rect.w - rr, rect.y + rr}, fc, {0, 0}}
	verts[2] = {{rect.x + rect.w - rr, rect.y + rect.h - rr}, fc, {0, 0}}
	verts[3] = {{rect.x + rr, rect.y + rect.h - rr}, fc, {0, 0}}
	vc := 4

	indices[0], indices[1], indices[2] = 0, 1, 3
	indices[3], indices[4], indices[5] = 1, 2, 3
	ic := 6

	corners := [4]struct {
		cx, cy, sx, sy: f32,
	} {
		{rect.x + rr, rect.y + rr, -1, -1}, // top-left, center vertex 0
		{rect.x + rect.w - rr, rect.y + rr, 1, -1}, // top-right, center vertex 1
		{rect.x + rect.w - rr, rect.y + rect.h - rr, 1, 1}, // bot-right, center vertex 2
		{rect.x - rr, rect.y + rect.h - rr, -1, 1}, // bot-left, center vertex 3
	}


	step := (math.PI * 0.5) / f32(segments)
	for i in 0 ..< segments {
		a1 := f32(i) * step
		a2 := f32(i + 1) * step
		for corner, j in corners {
			p1 := sdl.FPoint {
				corner.cx + math.cos(a1) * rr * corner.sx,
				corner.cy + math.sin(a1) * rr * corner.sy,
			}
			p2 := sdl.FPoint {
				corner.cx + math.cos(a2) * rr * corner.sx,
				corner.cy + math.sin(a2) * rr * corner.sy,
			}
			verts[vc] = {p1, fc, {0, 0}}
			verts[vc + 1] = {p2, fc, {0, 0}}
			indices[ic], indices[ic + 1], indices[ic + 2] = c.int(j), c.int(vc), c.int(vc + 1)
			vc += 2
			ic += 3
		}
	}

	edges := [4]struct {
		p0, p1: sdl.FPoint,
		c0, c1: c.int,
	} {
		{{rect.x + rr, rect.y}, {rect.x + rect.w - rr, rect.y}, 0, 1}, // top
		{{rect.x + rect.w, rect.y + rr}, {rect.x + rect.w, rect.y + rect.h - rr}, 1, 2}, // right
		{{rect.x + rect.w - rr, rect.y + rect.h}, {rect.x + rr, rect.y + rect.h}, 2, 3}, // bottom
		{{rect.x, rect.y + rect.h - rr}, {rect.x, rect.y + rr}, 3, 0}, // left
	}

	for e in edges {
		v0, v1 := c.int(vc), c.int(vc + 1)
		verts[vc] = {e.p0, fc, {0, 0}}
		verts[vc + 1] = {e.p1, fc, {0, 0}}
		indices[ic], indices[ic + 1], indices[ic + 2] = e.c0, v0, v1
		indices[ic + 3], indices[ic + 4], indices[ic + 5] = e.c1, e.c0, v1
		vc += 2
		ic += 6
	}

	assert(vc <= VERTS_MAX)
	assert(ic <= INDICES_MAX)
	sdl.RenderGeometry(
		data.renderer,
		nil,
		raw_data(verts[:]),
		c.int(vc),
		raw_data(indices[:]),
		c.int(ic),
	)
}

@(private = "file")
render_border :: proc(data: ^Clay_Render_Memory, rect: sdl.FRect, cfg: clay.BorderRenderData) {
	min_radius := min(rect.w, rect.h) / 2
	tl := min(cfg.cornerRadius.topLeft, min_radius)
	tr := min(cfg.cornerRadius.topRight, min_radius)
	bl := min(cfg.cornerRadius.bottomLeft, min_radius)
	br := min(cfg.cornerRadius.bottomRight, min_radius)

	col := color_u8(cfg.color)
	sdl.SetRenderDrawColor(data.renderer, col.r, col.g, col.b, col.a)

	if cfg.width.left > 0 {
		line := sdl.FRect{rect.x - 1, rect.y, f32(cfg.width.left), rect.h - tr - bl}
		sdl.RenderFillRect(data.renderer, &line)
	}
	if cfg.width.right > 0 {
		x := rect.x + rect.w - f32(cfg.width.right) + 1
		line := sdl.FRect{x, rect.y + tr, f32(cfg.width.right), rect.h - tr - br}
		sdl.RenderFillRect(data.renderer, &line)
	}
	if cfg.width.top > 0 {
		line := sdl.FRect{rect.x + tl, rect.y - 1, rect.w - tl - tr, f32(cfg.width.top)}
		sdl.RenderFillRect(data.renderer, &line)
	}
	if cfg.width.bottom > 0 {
		y := rect.y + rect.h - f32(cfg.width.bottom) + 1
		line := sdl.FRect{rect.x + bl, y, rect.w - bl - br, f32(cfg.width.bottom)}
		sdl.RenderFillRect(data.renderer, &line)
	}

	// Rounded corners as stroked arcs, thickness from nearer edge.
	if cfg.cornerRadius.topLeft > 0 {
		center := sdl.FPoint{rect.x + tl - 1, rect.y + tl - 1}
		render_arc(data, center, tl, 180, 270, f32(cfg.width.top), cfg.color)
	}
}

@(private = "file")
render_text :: proc(data: ^Clay_Render_Memory, rect: sdl.FRect, cfg: clay.TextRenderData) {
	assert(int(cfg.fontId) < len(data.fonts))
	font := data.fonts[cfg.fontId]

	ttf.SetFontSize(font, f32(cfg.fontSize))

	chars := cast(cstring)cfg.stringContents.chars
	text := ttf.CreateText(data.text_engine, font, chars, c.size_t(cfg.stringContents.length))
	defer ttf.DestroyText(text)

	col := color_u8(cfg.textColor)
	ttf.SetTextColor(text, col.r, col.g, col.b, col.a)
	ttf.DrawRendererText(text, rect.x, rect.y)
}

@(private = "file")
render_arc :: proc(
	data: ^Clay_Render_Memory,
	center: sdl.FPoint,
	radius, start_deg, end_deg, thickness: f32,
	color: clay.Color,
) {
	col := color_u8(color)
	sdl.SetRenderDrawColor(data.renderer, col.r, col.g, col.b, col.a)

	rad_start := start_deg * (math.PI / 180)
	rad_end := end_deg * (math.PI / 180)
	segments := clamp(int(radius * 1.5), SEGMENTS_BASE, ARC_SEGMENTS_MAX)
	angle_step := (rad_end - rad_start) / f32(segments)

	THICKNESS_STEP :: f32(0.4)

	points: [ARC_SEGMENTS_MAX + 1]sdl.FPoint = ---
	for t := THICKNESS_STEP; t < thickness - THICKNESS_STEP; t += THICKNESS_STEP {
		r := max(radius - t, 1)
		for i in 0 ..= segments {
			angle := rad_start + f32(i) * angle_step
			points[i] = {
				math.round(center.x + math.cos(angle) * r),
				math.round(center.y + math.sin(angle) * r),
			}
		}
		sdl.RenderLines(data.renderer, raw_data(points[:]), c.int(segments + 1))
	}
}

@(private = "file")
color_float :: proc "contextless" (col: clay.Color) -> sdl.FColor {
	return {col.r / 255, col.g / 255, col.b / 255, col.a / 255}
}

@(private = "file")
color_u8 :: proc "contextless" (col: clay.Color) -> [4]u8 {
	return {u8(col.r), u8(col.g), u8(col.b), u8(col.a)}
}

@(private = "file")
err_handler :: proc "c" (err: clay.ErrorData) {
	context = runtime.default_context()
	trace := cast(^Clay_Trace)err.userData
	if trace != nil {
		trace.had_error = true
	}

	msg := cast(string)(err.errorText.chars)[:err.errorText.length]

	err := fmt.tprintf(
		"[clay] %v: %s			phase=%s at %s:%d\n",
		err.errorType,
		msg,
		trace.phase if trace != nil else "?",
		trace.file if trace != nil else "?",
		trace.line if trace != nil else 0,
	)

	when ODIN_DEBUG {
		panic(err)
	} else {
		fmt.eprint(err)
	}
}

@(private = "file")
measure_text :: proc "c" (
	str: clay.StringSlice,
	cfg: ^clay.TextElementConfig,
	user_data: rawptr,
) -> clay.Dimensions {
	context = runtime.default_context()

	data := cast(^Clay_Render_Memory)user_data
	assert(data != nil)
	assert(int(cfg.fontId) < len(data.fonts))

	font := data.fonts[cfg.fontId]
	ttf.SetFontSize(font, f32(cfg.fontSize))

	w, h: c.int

	if !ttf.GetStringSize(font, (cstring)(str.chars), uint(str.length), &w, &h) {
		sdl.LogError(i32(sdl.LogCategory.ERROR), "Failed to measure text: %s", sdl.GetError())
	}

	return {f32(w), f32(h)}
}

// Keep SDL texture package loaded for texture rendering
_ :: img.LoadTexture

package platform

import sdl "vendor:sdl3"

// binding omits COUNT; `_ = 511` sentinel -> 512
KEY_COUNT :: int(max(sdl.Scancode)) + 1

Mouse_Button :: enum u8 {
	Left,
	Right,
	Middle,
}

Mouse_Input :: struct {
	pos:   [2]f32,
	delta: [2]f32,
	wheel: [2]f32,
}

Key_Press :: struct {
	key:  sdl.Keycode,
	mods: sdl.Keymod,
}

Text_Input :: struct {
	utf8:        [64]u8,
	utf8_len:    int,
	presses:     [32]Key_Press,
	presses_len: int,
	dropped:     int,
}

Input :: struct {
	// Mouse
	mouse:     Mouse_Input,
	btns_curr: bit_set[Mouse_Button],
	btns_prev: bit_set[Mouse_Button],

	// Keyboard
	keys_curr: [KEY_COUNT]bool,
	keys_prev: [KEY_COUNT]bool,
	text:      Text_Input,

	// Other
	quit:      bool,
}

input_frame_begin :: proc(inp: ^Input) {
	// Mouse state reset
	inp.btns_prev = inp.btns_curr
	inp.mouse.delta = {}
	inp.mouse.wheel = {}

	// Keyboard state reset
	inp.keys_prev = inp.keys_curr
	inp.text.utf8_len = 0
	inp.text.presses_len = 0
	inp.text.dropped = 0

	// Quit state reset (might not be needed)
	inp.quit = false
}

input_event_process :: proc(inp: ^Input, ev: ^sdl.Event) {
	#partial switch ev.type {
	case .QUIT:
		inp.quit = true
	case .MOUSE_MOTION:
		inp.mouse.pos = {ev.motion.x, ev.motion.y}
		inp.mouse.delta += {ev.motion.xrel, ev.motion.yrel}
	case .MOUSE_WHEEL:
		inp.mouse.wheel += {ev.wheel.x, ev.wheel.y}
	case .MOUSE_BUTTON_DOWN:
		if b, ok := mouse_button_from_sdl(ev.button.button); ok {
			inp.btns_curr += {b}
		}
	case .MOUSE_BUTTON_UP:
		if b, ok := mouse_button_from_sdl(ev.button.button); ok {
			inp.btns_curr -= {b}
		}
	case .KEY_DOWN:
		inp.keys_curr[int(ev.key.scancode)] = true

		if inp.text.presses_len < len(inp.text.presses) {
			inp.text.presses[inp.text.presses_len] = {ev.key.key, ev.key.mod}
			inp.text.presses_len += 1
		} else {
			inp.text.dropped += 1
		}
	case .KEY_UP:
		inp.keys_curr[int(ev.key.scancode)] = false
	case .TEXT_INPUT:
		src := cast([^]u8)ev.text.text
		for i := 0; src[i] != 0 && inp.text.utf8_len < len(inp.text.utf8); i += 1 {
			inp.text.utf8[inp.text.utf8_len] = src[i]
			inp.text.utf8_len += 1
		}
	}
}

@(require_results)
key_down :: proc(inp: ^Input, sc: sdl.Scancode) -> bool {
	return inp.keys_curr[int(sc)]
}

@(require_results)
key_pressed :: proc(inp: ^Input, sc: sdl.Scancode) -> bool {
	return inp.keys_curr[int(sc)] && !inp.keys_prev[int(sc)]
}

@(require_results)
key_released :: proc(inp: ^Input, sc: sdl.Scancode) -> bool {
	return !inp.keys_curr[int(sc)] && inp.keys_prev[int(sc)]
}

@(require_results)
mouse_down :: proc(inp: ^Input, b: Mouse_Button) -> bool {
	return b in inp.btns_curr
}

@(require_results)
mouse_pressed :: proc(inp: ^Input, b: Mouse_Button) -> bool {
	return b in inp.btns_curr && b not_in inp.btns_prev
}

@(require_results)
mouse_released :: proc(inp: ^Input, b: Mouse_Button) -> bool {
	return b not_in inp.btns_curr && b in inp.btns_prev
}

mouse_scroll :: proc(inp: ^Input) -> [2]f32 {

	return {}
}

@(private = "file")
mouse_button_from_sdl :: proc(b: u8) -> (Mouse_Button, bool) {
	switch b {
	case sdl.BUTTON_LEFT:
		return .Left, true
	case sdl.BUTTON_RIGHT:
		return .Right, true
	case sdl.BUTTON_MIDDLE:
		return .Middle, true
	}
	return {}, false
}
